// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.reminderimport timber.log.Timberimport android.app.NotificationChannelimport android.app.NotificationManagerimport android.app.PendingIntentimport android.content.Contextimport android.content.Intentimport android.media.RingtoneManagerimport android.os.Buildimport androidx.core.app.NotificationCompatimport androidx.work.CoroutineWorkerimport androidx.work.Dataimport androidx.work.WorkerParametersimport com.roshan.persona.productivity.alarm.EncryptedData/** * NOUS — Reminder Worker (Module 14 v1.2 — Step 14.2, CRITICAL). * * REAL [CoroutineWorker] that fires when a reminder is due. * * ## How it gets scheduled * * [ReminderEngine.scheduleReminder] builds a `OneTimeWorkRequest` with: *   - initial delay = `reminder.triggerAtMs - now` *   - tag = `"reminder_${reminder.id}"` (used for cancel/snooze) *   - input data = reminder id + label + encrypted body * * WorkManager handles Doze survival + battery optimization internally — * we do NOT use AlarmManager for reminders (per strategy v1.1 §"Fix 2"). * * ## What the worker does * * When WorkManager fires the worker (reminder time reached): *   1. Read reminder id + label + encrypted body from input data. *   2. Decrypt the body via [ReminderEncryptionHelper] (REAL AES-GCM). *   3. Create the notification channel (API 26+). *   4. Build a high-priority notification with SNOOZE + DISMISS actions. *   5. Post the notification. *   6. Return [Result.success] (reminder fires once — no retry on fail). * * ## FLAG_IMMUTABLE * * All action PendingIntents use `FLAG_IMMUTABLE` on API 31+ (mandatory * security requirement, per strategy v1.2 §"Improvement 2"). * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Fix 2</a> */class ReminderWorker(    appContext: Context,    params: WorkerParameters,) : CoroutineWorker(appContext, params) {    companion object {        private const val TAG = "ReminderWorker"        /** WorkManager input key for the reminder ID. */        const val KEY_REMINDER_ID = "reminder_id"        /** WorkManager input key for the reminder label. */        const val KEY_REMINDER_LABEL = "reminder_label"        /** WorkManager input key for the encrypted body IV (Base64). */        const val KEY_REMINDER_IV = "reminder_iv"        /** WorkManager input key for the encrypted body ciphertext (Base64). */        const val KEY_REMINDER_CIPHERTEXT = "reminder_ciphertext"        /** Notification channel ID for reminders. */        const val NOTIFICATION_CHANNEL_ID = "nous_reminder_channel"        /** Notification channel name (shown in Settings). */        const val NOTIFICATION_CHANNEL_NAME = "NOUS Reminders"        /** Base notification ID for reminders (reminder ID hash added). */        const val REMINDER_NOTIFICATION_ID_BASE = 20000    }    private val encryptionHelper = ReminderEncryptionHelper()    override suspend fun doWork(): Result {        val reminderId = inputData.getString(KEY_REMINDER_ID) ?: "unknown"        val label = inputData.getString(KEY_REMINDER_LABEL) ?: "Reminder"        val ivBase64 = inputData.getString(KEY_REMINDER_IV)        val ciphertextBase64 = inputData.getString(KEY_REMINDER_CIPHERTEXT)        Timber.tag(TAG).i("Reminder fired: '$label' (id=$reminderId).")        // Decrypt body (if present) — REAL AES-GCM decrypt via AndroidKeystore.        val body = if (ivBase64 != null && ciphertextBase64 != null) {            val encrypted = EncryptedData(ivBase64, ciphertextBase64)            encryptionHelper.decrypt(encrypted)        } else {            null        }        // Show notification (REAL NotificationCompat + NotificationManager).        showReminderNotification(applicationContext, reminderId, label, body)        return Result.success()    }    /**     * Build + post the reminder notification.     *     * Includes two action buttons:     *   - SNOOZE  → broadcasts [ReminderActionReceiver.ACTION_SNOOZE]     *   - DISMISS → broadcasts [ReminderActionReceiver.ACTION_DISMISS]     *     * Both actions use FLAG_IMMUTABLE PendingIntents (mandatory on API 31+).     */    private fun showReminderNotification(        context: Context,        reminderId: String,        label: String,        body: String?,    ) {        // 1. Create / fetch notification channel (API 26+).        createNotificationChannel(context)        // 2. Build SNOOZE action (FLAG_IMMUTABLE on API 31+).        val snoozeIntent = Intent(context, ReminderActionReceiver::class.java).apply {            action = ReminderActionReceiver.ACTION_SNOOZE            putExtra(ReminderActionReceiver.EXTRA_REMINDER_ID, reminderId)            putExtra(ReminderActionReceiver.EXTRA_LABEL, label)            // Pass encrypted body through (re-encrypted on snooze time).            putExtra(ReminderActionReceiver.EXTRA_IV, body?.let { inputData.getString(KEY_REMINDER_IV) })            putExtra(ReminderActionReceiver.EXTRA_CIPHERTEXT, body?.let { inputData.getString(KEY_REMINDER_CIPHERTEXT) })        }        val snoozePendingIntent = PendingIntent.getBroadcast(            context,            reminderId.hashCode(),            snoozeIntent,            pendingIntentFlags(),        )        // 3. Build DISMISS action (FLAG_IMMUTABLE on API 31+).        val dismissIntent = Intent(context, ReminderActionReceiver::class.java).apply {            action = ReminderActionReceiver.ACTION_DISMISS            putExtra(ReminderActionReceiver.EXTRA_REMINDER_ID, reminderId)        }        val dismissPendingIntent = PendingIntent.getBroadcast(            context,            reminderId.hashCode() + 1,  // Distinct request code from SNOOZE.            dismissIntent,            pendingIntentFlags(),        )        // 4. Build the notification.        val builder = NotificationCompat.Builder(context, NOTIFICATION_CHANNEL_ID)            .setSmallIcon(android.R.drawable.ic_popup_reminder)            .setContentTitle("📌 $label")            .apply {                if (!body.isNullOrBlank()) {                    setContentText(body)                    setStyle(NotificationCompat.BigTextStyle().bigText(body))                } else {                    setContentText("Reminder")                }            }            .setPriority(NotificationCompat.PRIORITY_HIGH)            .setCategory(NotificationCompat.CATEGORY_REMINDER)            .setSound(RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION))            .setVibrate(longArrayOf(0, 300, 200, 300))            .setAutoCancel(true)            .addAction(android.R.drawable.ic_media_play, "Snooze 5 min", snoozePendingIntent)            .addAction(android.R.drawable.ic_menu_close_clear_cancel, "Dismiss", dismissPendingIntent)        // 5. Post the notification.        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager ?: return        val notificationId = REMINDER_NOTIFICATION_ID_BASE + (reminderId.hashCode() and 0xFFF)        notificationManager.notify(notificationId, builder.build())        Timber.tag(TAG).d("Posted reminder notification (id=$reminderId, notifId=$notificationId).")    }    /**     * Create the reminder notification channel (REAL API 26+).     */    private fun createNotificationChannel(context: Context) {        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {            val channel = NotificationChannel(                NOTIFICATION_CHANNEL_ID,                NOTIFICATION_CHANNEL_NAME,                NotificationManager.IMPORTANCE_HIGH,            ).apply {                description = "NOUS reminder notifications"                enableVibration(true)                setSound(                    RingtoneManager.getDefaultUri(RingtoneManager.TYPE_NOTIFICATION),                    android.media.AudioAttributes.Builder()                        .setContentType(android.media.AudioAttributes.CONTENT_TYPE_SONIFICATION)                        .setUsage(android.media.AudioAttributes.USAGE_NOTIFICATION)                        .build(),                )            }            val manager = context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager ?: return            manager.createNotificationChannel(channel)        }    }    /**     * Compute PendingIntent flags with FLAG_IMMUTABLE on API 31+ (mandatory).     */    private fun pendingIntentFlags(): Int {        return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE        } else {            PendingIntent.FLAG_UPDATE_CURRENT        }    }}